import pathlib,sys,json,csv
root=pathlib.Path(sys.argv[1]);base=root/'external_untrusted/round6/r6_americas';notes=root/'bakeoff/notes/round6_local/r6_americas';out=root/'external_unlabelled/round6/r6_americas'
rows=json.loads((base/'sample_index.json').read_text(encoding='utf-8'))+json.loads((base/'extra_index.json').read_text(encoding='utf-8'))
info={
'mexico':('CNH / CNIH / SENER - Trion and Perdido','The public Trion access page links an inventory, not the well files. Package TP lists Trion-1 and Trion-1DL. Use licences are required. The Round 1 deepwater inventory lists Exploratus-101. The 18 April 2016 answers place Maximino-1 mud chromatography in the package disk and virtual data room; this is not a public full mud-log download.','2 Trion wells named in TP; other deepwater wells listed; 0 full logs confirmed','Public inventories and presentations. Full data via licence / bid package; no login used.','Use licences apply to underlying data; no training reuse licence established.'),
'brazil':('ANP BDEP / REATE','Public REATE onshore basin page is indexed by search. Direct Portuguese and English requests returned HTTP 503. No repeated retry after the second failure. No basin transfer link recovered. ANP FAQ describes requested data delivered with FTP credentials. PROMAR includes selected mature offshore areas, but no anonymous full log was confirmed.','Unknown usable logs; 0 downloaded','Public indexed landing page; local download blocked by 503. General BDEP route requires a request and credentials.','No image reuse terms established.'),
'trinidad':('MEEI','The public package inventory lists Mud Log or Lithology Descriptions for KK4-2 & 2ST2. It does not include those files. The 2013 room guidelines prohibit digital reproduction. The 2018 virtual room leaflet requires contact for access.','At least one inventory entry mentions mud logs; no full log downloaded','Public inventories; underlying data room needs arranged access.','Room guidelines prohibit photocopies and digital reproduction.'),
'colombia':('ANH / SGC EPIS','The official 2024 presentation renames BIP to FEIH and EPIS to FID. It describes the request flow. ANH FAQ describes contracted web access and a request / quotation route. The 2024 government service listing describes free advice with prior registration or an email request. These are different services and dates; old FAQ prices are not treated as current. No anonymous log file confirmed.','Unknown','Public process documents; underlying file supply requires a request.','No training reuse licence established.'),
'guyana':('Guyana Petroleum Management Programme','The public Well Activities page gives well names and locations. No full mud-log file was found there. This is a metadata route, not a confirmed log archive.','Unknown','Public well table downloaded without login.','No log reuse terms established.'),
'suriname':('Staatsolie','The public SHO 2023-2024 confidentiality agreement limits the receiving party to viewing and evaluating the data room. It prohibits download, print, recording and reproduction. No anonymous full mud log confirmed.','Unknown','Agreement is public; underlying room is restricted.','Viewing only under agreement; reproduction prohibited.')}
sources=[]
for key,(name,route,volume,access,terms) in info.items():
 docs=[]
 for r in rows:
  if r['source']!=key:continue
  docs.append(dict(url=r['url'],path=r.get('path'),bytes=r.get('bytes'),pages=r.get('pages'),raster_or_vector='mixed/text PDF' if r.get('pages') else 'HTML / access response',has_lith_column=False,has_legend=False,similarity=0,family_match=None,notes='No full mud/master log. Supporting inventory, presentation, metadata, access rules, or failed response. HTTP '+str(r.get('status',r.get('error')))))
 sources.append(dict(name=name,urls_seen=[r['url'] for r in rows if r['source']==key],bulk_route=route,n_available_estimate=volume,access=access,license_terms=terms,documents=docs))
sources[0]['urls_seen']+=['https://rondasmexico.energia.gob.mx/esp/asociaciones/pemex-2016/cnh-a1-trion2016/','https://www.pemex.com/saladeprensa/boletines_nacionales/Paginas/2017-063-nacional.aspx','https://www.gob.mx/cnh/prensa/el-centro-nacional-de-informacion-de-hidrocarburos-cnih-lanza-su-portal-de-informacion-tecnica-pit']
sources[1]['urls_seen']+=['https://www.gov.br/anp/pt-br/acesso-a-informacao/perguntas-frequentes']
sources[3]['urls_seen']+=['https://www.anh.gov.co/en/la-anh/informacion-de-interes/faq/','https://visorsuit.funcionpublica.gov.co/auth/visor?fi=42853']
dead=['No public full mud/master log was confirmed in this lane. Do not count inventory entries as acquired logs.','The target of about 15 full-log sample documents could not be reached: no eligible file route was found. Supporting PDFs do not satisfy that target.','REATE returned 503 twice across Portuguese and English pages. It remains a recovery lead, not proof that its data need login.','The old rondasmexico.gob.mx PDF returned Cloudflare 522. The linked energia.gob.mx host worked.','No page met similarity >=2. Conversion, boxes, and bulk download were therefore not performed.','BSEE, forbidden wells, sealed verification files, and eval images were not used.']
triage=dict(family='Gulf of Mexico 3-panel deepwater mud/master logs',sources=sources,dead_ends=dead)
(base/'triage.json').write_text(json.dumps(triage,indent=2,ensure_ascii=False),encoding='utf-8')
out.mkdir(parents=True,exist_ok=True);(out/'images').mkdir(exist_ok=True);(out/'bbox_annotation').mkdir(exist_ok=True)
header=next(csv.reader((root/'external_unlabelled/round5/manifest.csv').open(encoding='utf-8',newline='')))
with (out/'manifest.csv').open('w',encoding='utf-8',newline='') as f:csv.writer(f).writerow(header)
pdfs=[r for r in rows if r.get('pages')];pages=sum(r['pages'] for r in pdfs)
report=['# r6_americas research result','','No public full mud log or master log was confirmed. No new data match any of the seven families. Best observed similarity: 0/3.','','## Counts','',f'- Supporting PDF documents downloaded: {len(pdfs)}.',f'- Pages in these PDFs: {pages}. These are not mud-log pages.','- Full logs: 0. Converted pages: 0. Labelled windows: 0.','- About 15 full-log samples: not reached. No eligible file route found.','','## Routes in follow-up order','','All observed routes have zero confirmed matching-image yield. Thus the requested similarity x volume x anonymous-access product is 0 for each. The order below gives recovery priority, not a measured positive score.','']
for n,key in enumerate(['brazil','mexico','trinidad','colombia','guyana','suriname'],1):
 s=next(s for s in sources if s['name']==info[key][0]);report += [f'### {n}. {s["name"]}','',s['bulk_route'],'',f'Access: {s["access"]}',f'Volume: {s["n_available_estimate"]}',f'Terms: {s["license_terms"]}','','Sources: '+', '.join(f'[{i+1}]({u})' for i,u in enumerate(s['urls_seen'])),'']
report+=['## Visual check','','The contact sheet places a non-eval Gulf reference beside five public source samples. The reference is 60811405350100_shenzi-sb203-st00bp01_mudlog_4320-27400. The eval list was checked before the image was opened. The second sheet shows all 28 pages of the Mexican bid presentation. None is a full mud log.','','- [Contact sheet](contact_sheet.png)','- [Mexican presentation pages](mexico_presentation_sheet.png)','','## Limits and next step','','Recover the REATE basin transfer page first. If it works, sample about 15 actual PAG or composite-log files before bulk work. For Mexico, the public inventory is useful evidence of held files, but the underlying route needs a licence. Do not infer a layout score from a well name or inventory checkbox.','','The unlabelled folder has an empty manifest with the round5 column format. No low-score page was added. No training, tuning, commits or pushes were done.','','Checks: run validate.py after the final write.']
(notes/'REPORT.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
print(f'Written: {len(pdfs)} supporting PDF documents, {pages} pages; 0 full logs; 0 conversions; 0 labelled windows.')
